public object AddNewItem(object param)
{
	if (!string.IsNullOrEmpty(customInstanceFullName))
	{
		return ActivatorWrap.CreateInstance(customInstanceFullName, new object[2] { param, Name });
	}
	Assembly assembly = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault((Assembly p) => string.Equals(p.GetName().Name, $"{Info}Cs"));
	Assembly assembly2 = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault((Assembly p) => string.Equals(p.GetName().Name, $"{Info}Control"));
	if (assembly == null)
	{
		ActivatorWrap.LoadAssembly($"{DirPath}\\{Info}Cs.dll");
		assembly = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault((Assembly p) => string.Equals(p.GetName().Name, $"{Info}Cs"));
	}
	if (assembly2 == null)
	{
		string text = $"{DirPath}\\Librarys.Config";
		if (File.Exists(text))
		{
			string[] libs = GetLibs(text);
			libs.ToList().ForEach((string p) =>
			{
				string text2 = $"{DirPath}\\{p}";
				if (File.Exists(text2))
				{
					ActivatorWrap.LoadAssembly(text2);
				}
			});
		}
		if (File.Exists($"{DirPath}\\{Info}Control.dll"))
		{
			ActivatorWrap.LoadAssembly($"{DirPath}\\{Info}Control.dll");
		}
	}
	Type type = assembly.GetTypes().FirstOrDefault((Type p) => typeof(IVmModule).IsAssignableFrom(p));
	return ActivatorWrap.CreateInstance(type, new object[1] { param });
}

