private void AddInput()
{
    var initialName = $"in_{Inputs.Count + 1}";
    Inputs.Add(new SubroutineInputConfig
    {
        Name = initialName,
        BindingKey = initialName,
        TypeName = SelectedInputTypeName
    });
}

private void AddOutput()
